      "policy_quote": "Before any action that changes a booking (`cancel_booking`, `change_vehicle_class`, `add_driver`, `issue_refund`), state the details and obtain explicit confirmation (\"yes\"/\"да\").",
      "requirement": "Must obtain explicit confirmation from the user before canceling the booking."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "A booking can be cancelled with `cancel_booking`. The cancellation fee depends on the time remaining until `pickup_time`: - 48 hours or more before pickup: no fee (`fee_usd` = 0); - less than 48 hours before pickup: a fee of 50 USD (`fee_usd` = 50).",
      "requirement": "Must ensure the correct cancellation fee (`fee_usd`) is set based on time remaining until pickup."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "Exception: customers with `tier` equal to `gold` never pay a cancellation fee (`fee_usd` = 0), regardless of timing.",
      "requirement": "Customer with `tier` `gold` must have `fee_usd` set to 0, regardless of timing."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "The fee is charged automatically by the system to the booking's payment method; you must pass the correct `fee_usd`.",
      "requirement": "Must pass the correct `fee_usd` to ensure the fee is charged to the booking's payment method."
    }
  ]
